// Administration is a scope, not a string comparison against a column. The old
// `session.role === 'admin'` shape could not be checked at build time, could
// not be granted through the console, and said nothing about *which* admin
// capability was needed.
//
// Defined here rather than beside its `wireHTTP` call: a file that both defines
// a function and wires it yields "metadata not found" from the inspector, and
// the wiring is skipped at startup. `DELETE /orders/:orderId` was wired,
// documented, and absent from the running server for exactly that reason.
export const deleteOrder = pikkuFunc({
  func: async ({ kysely }, { orderId }: { orderId: string }) => {
    await kysely
      .deleteFrom('order')
      .where('orderId', '=', orderId)
      .execute();
  },
  scopes: ['orders'],
});

funcThreeParams:
// Three parameters, always: services, data, wire.
//   services — your toolbox (db, logger, queues)
//   data     — the typed input, wherever it arrived from
//   wire     — the protocol context (session, http, channel, rpc)
export const getOrder = pikkuFunc({
  expose: true,
  description:
    'Get a single order. Users can only access their own orders.',
  input: GetOrderInput,
  output: GetOrderOutput,
  func: async ({ kysely }, { orderId }, { session }) => {
    const order = await kysely
      .selectFrom('order')
      .selectAll()
      .where('orderId', '=', orderId)
      .executeTakeFirst();

    if (!order) throw new Error('Order not found');
    if (
      order.userId !== session.userId &&
      session.role !== 'admin'
    ) {
      throw new Error('Forbidden');
    }

    const items = await kysely
      .selectFrom('orderItem')
      .innerJoin('item', 'item.itemId', 'orderItem.itemId')
      .select([
        'orderItem.itemId',
        'item.name',
        'orderItem.quantity',
        'orderItem.unitPriceCents',
      ])
      .where('orderItem.orderId', '=', orderId)
      .execute();

    return {
      orderId: order.orderId,
      status: order.status,
      totalCents: order.totalCents,
      // Nullable: a walk-through order placed before an address was captured
      // has none, and returning null beats throwing on a read.
      shippingAddress: order.shippingAddress
        ? JSON.parse(order.shippingAddress)
        : null,
      items: items.map((i) => ({
        ...i,
        lineTotalCents: i.unitPriceCents * i.quantity,
      })),
      createdAt: order.createdAt,
    };
  },
});

