    const basket = await kysely
      .selectFrom('basket')
      .select('updatedAt')
      .where('userId', '=', session.userId)
      .executeTakeFirst();

    return (
      basket != null &&
      new Date(basket.updatedAt) > new Date(Date.now() - 86_400_000)
    );
  },
);

