  { basketId: string },
  { basketId: string }
>({
  func: async ({ kysely }, { basketId }, { session }) => {
    const basket = await kysely
      .selectFrom('basket')
      .selectAll()
      .where('basketId', '=', basketId)
      .executeTakeFirst();
    if (!basket) {
      throw new NotFoundError(`Basket ${basketId} not found`);
    }

    if (
      basket.userId !== session.userId &&
      session.role !== 'admin'
    ) {
      throw new ForbiddenError('Access denied');
    }

    return { basketId };
  },
});

