  title: 'Process an order end-to-end',
  tags: ['orders'],
  input: z.object({ orderId: z.string() }),
  func: async ({ logger }, data, { rpc }) => {
    logger.info(`Processing order ${data.orderId}`);

    const order = await rpc.invoke('getOrder', {
      orderId: data.orderId,
