wa-wf-poll:
export const triggerAndWait = pikkuSessionlessFunc({
  func: async ({ workflowService }, _data, { rpc }) => {
    // Start workflow
    const { runId } = await rpc.startWorkflow('checkoutWorkflow', {
      basketId: 'basket-123',
      userId: 'user-456',
      shippingAddress: {
        line1: '1 High St',
        city: 'London',
        postcode: 'SW1A 1AA',
        country: 'GB',
      },
    });

    // Poll for completion
    const maxAttempts = 30;
    const pollIntervalMs = 1000;

    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      const run = await workflowService.getRun(runId);

      if (!run) {
        throw new Error(`Workflow not found: ${runId}`);
      }

      if (run.status === 'completed') {
        return run.output;
      }

      if (run.status === 'failed') {
        throw new Error(run.error?.message || 'Workflow failed');
      }

      if (run.status === 'cancelled') {
        throw new Error('Workflow was cancelled');
      }

      await new Promise((resolve) =>
        setTimeout(resolve, pollIntervalMs),
      );
    }

    throw new Error(
      `Workflow timeout after ${maxAttempts} attempts`,
    );
  },
});

