    charge: {
      next: 'finalize',
      input: (ref) => ({
        orderId: ref('createOrder', 'orderId'),
        totalCents: ref('validate', 'totalCents'),
      }),
    },
    finalize: {
      input: (ref) => ({
        orderId: ref('createOrder', 'orderId'),
