          accessToken: string;
          phoneId: string;
          verifyToken: string;
        }>('WHATSAPP')
      ).reveal();
      return createWhatsAppAdapter({
        accessToken,
        phoneId,
        verifyToken,
      });
    },
    func: handleMessage,
  });
}

wb-gateway-middleware:
export const rateLimit = pikkuMiddleware(
  async ({ logger }, wire, next) => {
    if (!wire.gateway) {
      throw new InvalidMiddlewareWireError(
        'rateLimit is for gateways',
      );
    }
    const { senderId, platform } = wire.gateway;
    logger.info({ event: 'gateway_message', platform, senderId });

    // Reply directly and skip the handler when the sender is over the limit
    const overLimit = false;
    if (overLimit) {
      await wire.gateway.send({
        text: 'Too many messages. Please wait.',
      });
      return;
    }
    await next();
  },
);

