shopServices:
export const createSingletonServices = pikkuServices(
  async (config, existingServices) => {
    const variables =
      existingServices?.variables ??
      new TypedVariablesService(new LocalVariablesService());
    const secrets =
      existingServices?.secrets ??
      new TypedSecretService(new LocalSecretService(variables));
    const logger =
      existingServices?.logger ?? new JsonConsoleLogger();
    const schema =
      existingServices?.schema ?? new CFWorkerSchemaService(logger);
    const emailService =
      existingServices?.emailService ??
      new GeneratedTemplateEmailService({
        delegate: new LocalEmailService(),
      });
    // The durable audit sink. In a deployed stage fabric injects the platform's
    // audit service; locally it falls back to a no-op so nothing is persisted.
    const audit = existingServices?.audit ?? new NoopAuditService();
    // kysely is injected by pikku dev (node:sqlite) or the CF Worker workflow (libsql).
    // The template never constructs its own dialect — dialects are fabric/runtime
    // concerns — so it must always be provided by the runtime.
    if (!existingServices?.kysely) {
      throw new Error(
        'kysely service was not injected by the runtime (pikku dev / fabric)',
      );
    }
    const kysely: Kysely<DB> = existingServices.kysely;

    // Per-user credential store (wire.getCredential) — needed by addons imported
    // with --auth per-user/delegated. A deployed stage injects it: credentials are
    // sealed to the stage, and only its secrets Worker holds the key. There is no
    // fallback because there is no key to fall back to — the template used to
    // build a `KyselyCredentialService` from a `CREDENTIALS_KEY` secret, which was
    // the stage's own KEK handed to every unit. Outside a stage the app runs fine
    // and credential-using addon calls fail with a clear error from the addon's
    // wire services; wire your own `credentialService` here if you need one.
    const credentialService = existingServices?.credentialService;

    const litellmProxyUrl = process.env.LITELLM_PROXY_URL ?? null;
    const litellmApiKey = process.env.LITELLM_API_KEY ?? null;
    let agentRunner: VercelAgentRunner | undefined;
    if (litellmProxyUrl && litellmApiKey) {
      // The AI SDKs (~3MB) are stubbed out of non-agent units at bundle time —
      // only units with the `ai-model` capability keep them. So import them
      // dynamically and guard on the module resolving to a real export; in a
      // stubbed unit the import yields `{}` and the runner is simply not built.
      const aiVercel = await import('@pikku/ai-vercel');
      const aiSdk = await import('@ai-sdk/openai-compatible');
      if (
        aiVercel.VercelAgentRunner &&
        aiSdk.createOpenAICompatible
      ) {
        const litellmProvider = aiSdk.createOpenAICompatible({
          name: 'litellm',
          baseURL: litellmProxyUrl,
          apiKey: litellmApiKey,
        });
        agentRunner = new aiVercel.VercelAgentRunner({
          openai: (modelId: string) =>
            litellmProvider.chatModel(modelId),
          anthropic: (modelId: string) =>
            litellmProvider.chatModel(modelId),
          google: (modelId: string) =>
            litellmProvider.chatModel(modelId),
          deepseek: (modelId: string) =>
            litellmProvider.chatModel(modelId),
        });
      }
    }

    // Without a ScopeService no user can hold any scope, so every function that
    // requires one denies everybody — `defineScope`, `defineSystemRole` and the
    // role grants `pikku persona sync` writes all exist and none of them reach a
    // request. It resolves userId -> roles -> scopes out of the four pikku_* tables.
    //
    // Built as the concrete class rather than the `ScopeService` interface because
    // `init()` is the implementation's, not the contract's. It *requires* the four
    // tables rather than creating them, and throws pointing at `pikku db generate`
    // if they are missing. The cast is the app's own `DB` — which
    // includes the pikku_* tables — against the narrower shape the service
    // declares; the two differ only in kysely's internal builder generics.
    let scopeService = existingServices?.scopeService;
    if (!scopeService) {
      const kyselyScopes = new KyselyScopeService(
        kysely as unknown as Kysely<KyselyPikkuDB>,
      );
      await kyselyScopes.init();
      scopeService = kyselyScopes;
    }

    // The definitions in scopes.ts and roles.ts are declarations until something
    // writes them down. Nothing else does, and a role with no row cannot be
    // granted — `addUserToRole` fails the pikku_role_scopes foreign key, which is
    // how persona provisioning discovers it.
    await scopeService.syncScopes(SCOPES);
    await scopeService.syncSystemRoles(SYSTEM_ROLES);

    // Workflows are declared in this project, so a workflowService is not
    // optional — without one the CLI refuses to generate (PKU600) and a run has
    // nowhere to keep its state between steps.
    // The workflow service serialises orchestration and step claims on a lease, so
    // it is built over the same lease service the app registers.
    const leaseService =
      existingServices?.leaseService ??
      new KyselyLeaseService(
        kysely as unknown as Kysely<KyselyPikkuDB>,
      );
    await (leaseService as { init?: () => Promise<void> }).init?.();

    const workflowService =
      existingServices?.workflowService ??
      new SQLiteKyselyWorkflowService(kysely as any, {
        leaseService,
      });
    await (
      workflowService as { init?: () => Promise<void> }
    ).init?.();

    // The shop assistant declares `memory`, and memory is only ever as durable as
    // the storage behind it — with no `agentStorage` registered the agent still
    // answers, it just forgets between turns. One instance covers `agentStorage`
    // and `agentRunState`: KyselyAgentStorageService implements both, and threads
    // and runs share the same tables, so splitting them across two instances would
    // only duplicate the connection. `init()` requires the agent_* tables (created
    // by db/sqlite/0005-pikku-runtime.sql) rather than creating them.
    const agentStorage =
      (existingServices?.agentStorage as
        KyselyAgentStorageService | undefined) ??
      new KyselyAgentStorageService(
        kysely as unknown as Kysely<KyselyPikkuDB>,
      );
    await agentStorage.init();

    // Read-only, and only the Console reads it — the agent itself never does.
    const agentRunService =
      existingServices?.agentRunService ??
      new KyselyAgentRunService(
        kysely as unknown as Kysely<KyselyPikkuDB>,
      );

    return {
      ...(existingServices ?? {}),
      config,
      scopeService,
      workflowService,
      leaseService,
      variables,
      secrets,
      schema,
      logger,
      emailService,
      audit,
      kysely,
      // Constructed once here rather than read per call: the payment provider's
      // credentials belong to service construction, and functions cannot reach
      // `secrets` at all (every function-facing services type is bounded by
      // SecretlessServices).
      ...(credentialService ? { credentialService } : {}),
      ...(agentRunner ? { agentRunner } : {}),
      agentStorage,
      agentRunState: agentStorage,
      agentRunService,
    };
  },
);

shopWireServices:
export const createWireServices = pikkuWireServices(
  async (singletonServices, wire) => {
    if (!singletonServices.audit) {
      return {};
    }
    const auditLog = createInvocationAudit(
      singletonServices.audit,
      wire,
    );
    // auditLog is ALWAYS injected, but `auditLog.write(...)` only PERSISTS when this
    // function set `audit: true` — createInvocationAudit gates on wire.audit, so
    // without it write() is a warn-only no-op (see @pikku/core audit-service.ts).
    // `auditLog.config` is set ONLY when audit: true is on, and when it is, ALSO wrap
    // kysely so every query is captured and the runner flushes the buffer on close.
    // Without audit: true, leave the plain kysely untouched — no per-query overhead.
    if (!auditLog.config) {
      return { auditLog };
    }
    return {
      auditLog,
      kysely: createAuditedKysely(singletonServices.kysely, {
        audit: auditLog,
      }),
    };
  },
);

workflowSteps:
// Every step of a DSL workflow is an ordinary pikku function. That is what
// makes a step retryable on its own, replayable from the durable log, and
// visible as a node in the generated workflow graph.
export const validateBasket = pikkuSessionlessFunc({
  description:
    'Confirm the basket has items and enough stock to sell.',
  func: async ({ kysely }, { basketId }: { basketId: string }) => {
    const rows = await kysely
      .selectFrom('basketItem')
      .innerJoin('item', 'item.itemId', 'basketItem.itemId')
      .select([
        'basketItem.itemId',
        'basketItem.quantity',
        'item.stock',
        'item.name',
        'item.priceCents',
      ])
      .where('basketItem.basketId', '=', basketId)
      .execute();

    if (rows.length === 0) throw new Error('Basket is empty');
    for (const i of rows) {
      if (i.quantity > i.stock)
        throw new Error(`Insufficient stock for "${i.name}"`);
    }

    return {
      items: rows.map((i) => ({
        itemId: i.itemId,
        quantity: i.quantity,
        priceCents: i.priceCents,
      })),
      totalCents: rows.reduce(
        (s, i) => s + i.priceCents * i.quantity,
        0,
      ),
    };
  },
});

shopSecretUsage:
// Note what is *absent* here: `secrets`.
//
// Every function-, permission- and auth-facing services type in pikku is
// bounded by `SecretlessServices`, which omits `secrets` outright. A function
// cannot read one, so a secret cannot leak through a return value, a log line
// or an error thrown from business logic — the class of bug you only find in
// somebody else's incident report.
//
// Secrets are read once, where they are needed. `chargeCard` asks the Stripe
// addon to create a payment intent; `STRIPE_SECRET_KEY` is the addon's secret
// and never crosses into this function, so it cannot be logged here, returned
// here, or attached to an error thrown here.
//
// This is the step the checkout workflow actually runs. The point used to be
// made by a second, unwired copy of the same call that existed only to be
// quoted — so the documented example was the one piece of payment code no
// shopper ever reached.
export const chargeCard = pikkuSessionlessFunc({
  // Invoked by name from `createOrder` as well as by the workflow, so one
  // charge path exists rather than two that can drift.
  expose: true,
  description: 'Charge the card through Stripe.',
  func: async (
    { logger },
    data: {
      orderId: string;
      totalCents: number;
      cardToken?: string;
    },
    { rpc },
  ) => {
    // The order id goes in the payment intent's metadata because that is the
    // only way it comes back: `applyStripeEvent` reads it off the verified
    // webhook event to decide which order was paid. Stripe knows nothing about
    // our ids otherwise.
    const intent = await rpc.invoke('stripe:paymentIntentCreate', {
      amount: data.totalCents,
      currency: 'gbp',
      ...(data.cardToken
        ? { paymentMethod: data.cardToken, confirm: true }
        : {}),
      metadata: { orderId: data.orderId },
      // Charging twice for one order is the expensive failure here, and a
      // workflow step is retried by design.
      idempotencyKey: `order_${data.orderId}`,
      description: `Order ${data.orderId}`,
    });

    logger.info({
      event: 'payment_intent_created',
      orderId: data.orderId,
      status: intent.status,
    });

    return intent.status === 'succeeded'
      ? { status: 'succeeded' as const, providerRef: intent.id }
      : { status: 'failed' as const, reason: intent.status };
  },
});

queuePublish:
// Publishing to a queue: `queueService.add(name, payload)`, typed against the
// queue's declared payload shape.
//
// This is the step that actually sends a receipt. The example used to be
// `placeOrder`, which inserted an order with a zero total and an empty address
// purely to have something to queue about, and which nothing ever called.
export const finalizeOrder = pikkuSessionlessFunc({
  description:
    'Record the outcome, and on success clear the basket and queue the receipt.',
  func: async (
    { kysely, queueService },
    data: {
      orderId: string;
      basketId: string;
      userId: string;
      status: 'paid' | 'payment_failed';
    },
  ) => {
    await kysely
      .updateTable('order')
      .set({
        status: data.status,
        updatedAt: new Date().toISOString(),
      })
      .where('orderId', '=', data.orderId)
      .execute();

    if (data.status === 'paid') {
      await kysely
        .deleteFrom('basketItem')
        .where('basketId', '=', data.basketId)
        .execute();
      await queueService?.add('send-order-confirmation', {
        orderId: data.orderId,
        userId: data.userId,
      });
    }
  },
});

wireWorkflow:
// The workflow body is the plan, not the work: each `workflow.do` names a step
// and the function that performs it. Pikku records every step in a durable log,
// so a crash mid-payment resumes at the step that failed rather than charging
// the card twice.
export const checkoutWorkflow = pikkuWorkflowFunc<
  {
    basketId: string;
    userId: string;
    shippingAddress: ShippingAddress;
    cardToken?: string;
  },
  {
    orderId: string;
    status: 'paid' | 'payment_failed';
    totalCents: number;
  }
>({
  expose: true,
  func: async (_services, data, { workflow }) => {
    const basket = await workflow.do(
      'Validate basket',
      'validateBasket',
      {
        basketId: data.basketId,
      },
    );

    const order = await workflow.do(
      'Create order',
      'createOrderRecord',
      {
        userId: data.userId,
        totalCents: basket.totalCents,
        shippingAddress: data.shippingAddress,
        items: basket.items,
      },
    );

    // Safely retried if the payment provider times out.
    const payment = await workflow.do(
      'Process payment',
      'chargeCard',
      {
        orderId: order.orderId,
        totalCents: basket.totalCents,
        cardToken: data.cardToken,
      },
    );

    const status =
      payment.status === 'succeeded'
        ? ('paid' as const)
        : ('payment_failed' as const);

    await workflow.do('Finalize', 'finalizeOrder', {
      orderId: order.orderId,
      basketId: data.basketId,
      userId: data.userId,
      status,
    });

    return {
      orderId: order.orderId,
      status,
      totalCents: basket.totalCents,
    };
  },
});

checkoutWorkflow:
// The workflow body is the plan, not the work: each `workflow.do` names a step
// and the function that performs it. Pikku records every step in a durable log,
// so a crash mid-payment resumes at the step that failed rather than charging
// the card twice.
export const checkoutWorkflow = pikkuWorkflowFunc<
  {
    basketId: string;
    userId: string;
    shippingAddress: ShippingAddress;
    cardToken?: string;
  },
  {
    orderId: string;
    status: 'paid' | 'payment_failed';
    totalCents: number;
  }
>({
  expose: true,
  func: async (_services, data, { workflow }) => {
    const basket = await workflow.do(
      'Validate basket',
      'validateBasket',
      {
        basketId: data.basketId,
      },
    );

    const order = await workflow.do(
      'Create order',
      'createOrderRecord',
      {
        userId: data.userId,
        totalCents: basket.totalCents,
        shippingAddress: data.shippingAddress,
        items: basket.items,
      },
    );

    // Safely retried if the payment provider times out.
    const payment = await workflow.do(
      'Process payment',
      'chargeCard',
      {
        orderId: order.orderId,
        totalCents: basket.totalCents,
        cardToken: data.cardToken,
      },
    );

    const status =
      payment.status === 'succeeded'
        ? ('paid' as const)
        : ('payment_failed' as const);

    await workflow.do('Finalize', 'finalizeOrder', {
      orderId: order.orderId,
      basketId: data.basketId,
      userId: data.userId,
      status,
    });

    return {
      orderId: order.orderId,
      status,
      totalCents: basket.totalCents,
    };
  },
});

workflowHTTPWiring:
